const massPoints=[];let seed=64171;function random(){seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;}for(let i=0;i<950;i++){const z=2*random()-1,az=TAU*random(),r=Math.cbrt(random()),q=Math.sqrt(1-z*z);massPoints.push({x:r*q*Math.cos(az),y:r*q*Math.sin(az),z:r*z});}massPoints.sort((a,b)=>a.z-b.z);
