ctx.strokeStyle=window.BookTheme.color('#5d929a90');ctx.lineWidth=1;ctx.setLineDash([3,6]);ctx.beginPath();ctx.arc(cx,cy,R,0,TAU);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle=window.BookTheme.color('#223942');ctx.beginPath();ctx.moveTo(cx-R-12,cy);ctx.lineTo(cx+R+12,cy);ctx.moveTo(cx,cy-R-12);ctx.lineTo(cx,cy+R+12);ctx.stroke();
