function relaxation(){const n=10**s.logN,v=P.relaxation(n,s.crossing),data=d3.range(121).map(i=>{const n=10**(2+i/12);return {n,r:P.relaxation(n,s.crossing).ratio};}),p=plot('relax-chart',d3.scaleLog().domain([100,1e12]),d3.scaleLog().domain([1,1e10]),'粒子数 N','tᵣₑₗₐₓ / t꜀ᵣₒₛₛ');curve(p,data,d=>d.n,d=>d.r);selected(p,n,v.ratio);$('relax-n-value').textContent=n.toExponential(2);$('relax-n').setAttribute('aria-valuetext',n.toExponential(2)+' 个粒子');$('relax-crossing-value').textContent=fmt(s.crossing,0);$('relax-ratio').textContent=sci(v.ratio);$('relax-time').textContent=sci(v.timeMyr/1000);$('relax-result').textContent=`一个穿越时间为${fmt(s.crossing,0)} Myr，二体弛豫约需 ${sci(v.ratio)} 次穿越。${s.logN<4?'粒子较少时，弱遭遇估计只能作粗略参考。':'在这个估计中，增加粒子数会使二体弛豫相对更慢。'}“无碰撞”并不代表没有整体引力作用。`;}
bind('relax-n',relaxation);bind('relax-crossing',relaxation);
function mix(){const v=P.phaseMixing(s.mixTime,s.slope),initial=P.phaseMixing(0,s.slope),{c,ctx,w,h}=canvas('mix-canvas'),mobile=w<500,panels=mobile?[{x:0,y:0,w,h:h/2},{x:0,y:h/2,w,h:h/2}]:[{x:0,y:0,w:w/2,h},{x:w/2,y:0,w:w/2,h}],color=d3.scaleLinear().domain([.8,1.2]).range([C.cyan,C.gold]);[initial,v].forEach((data,i)=>{const panel=panels[i],cx=panel.x+panel.w/2,cy=panel.y+panel.h/2+8,R=Math.min(panel.w-54,panel.h-75)/3.6;ctx.fillStyle=C.muted;ctx.font='11px -apple-system,sans-serif';ctx.textAlign='left';ctx.fillText(i===0?'初始分布 · t=0':'当前分布 · t='+fmt(s.mixTime,1),panel.x+15,panel.y+23);ctx.strokeStyle=C.line;ctx.lineWidth=.8;ctx.beginPath();ctx.moveTo(cx-1.65*R,cy);ctx.lineTo(cx+1.65*R,cy);ctx.moveTo(cx,cy-1.65*R);ctx.lineTo(cx,cy+1.65*R);ctx.stroke();for(const J of [.8,1,1.2]){ctx.setLineDash([3,6]);ctx.beginPath();ctx.arc(cx,cy,Math.sqrt(2*J)*R,0,TAU);ctx.stroke();}ctx.setLineDash([]);for(const point of data.points){ctx.fillStyle=color(point.J);ctx.beginPath();ctx.arc(cx+point.x*R,cy-point.p*R,mobile?1.25:1.4,0,TAU);ctx.fill();}ctx.fillStyle=C.muted;ctx.fillText('x',cx+1.65*R,cy-7);ctx.fillText('p',cx+7,cy-1.65*R);ctx.textAlign='center';ctx.fillText('正则相空间 · 固定坐标范围',cx,panel.y+panel.h-13);ctx.textAlign='left';});$('mix-slope-value').textContent=fmt(s.slope,2);$('mix-time-value').textContent=fmt(s.mixTime,1);$('mix-shear').textContent=fmt(v.shear,2);$('mix-area').textContent=fmt(v.area);$('mix-count').textContent=v.points.length;$('mix-result').textContent=`相空间面积 ΔJ·Δθ₀=${fmt(v.area)} 保持不变，颜色追踪初始 J。${s.slope===0?'所有轨道角频率相同，分布只作刚性旋转，没有差分剪切。':'不同 J 的相点以不同角频率运动；丝状图案来自可逆剪切，不是粒子碰撞。'}`;c.setAttribute('aria-label',`初始与当前正则相空间，t=${fmt(s.mixTime,1)}，频率梯度${fmt(s.slope,2)}，差分相位${fmt(v.shear,2)}，细粒度面积${fmt(v.area)}不变。`);}
bind('mix-slope',mix,'mix-play');bind('mix-time',mix,'mix-play');$('mix-reset').addEventListener('click',()=>{stop('mix-play');s.mixTime=0;$('mix-time').value=0;save();mix();});$('mix-rigid').addEventListener('click',()=>{stop('mix-play');s.slope=0;$('mix-slope').value=0;save();mix();});$('mix-play').addEventListener('click',()=>{if(running.has('mix-play')){stop('mix-play');return;}if(s.mixTime>=40-.001)s.mixTime=0;animate('mix-play',s.mixTime,40,t=>{s.mixTime=t;$('mix-time').value=t;},mix);});
const containers=['similarity-concept','similarity-concept','ellipsoid-concept','equilibrium-concept','relaxation-concept','hierarchy-concept'];window.CollapseConcepts.forEach((item,i)=>{const article=document.createElement('article');article.className='concept-reading';const h=document.createElement('h3');h.textContent=item.title;const p=document.createElement('p');p.textContent=item.body;const caveat=document.createElement('p');caveat.className='concept-caveat';caveat.textContent=item.caveat;const ref=document.createElement('small');ref.textContent=item.section;article.append(h,p,caveat,ref);$(containers[i]).append(article);});
