function tutor(prompt){window.showTutor('我在学习 Mo, van den Bosch & White (2010)《Galaxy Formation and Evolution》第5章。'+prompt+' 请逐步解释物理意义，核对单位和适用范围，并区分教材结论、教学模型和额外推断；不要把这个实验称为真实观测或自洽N体模拟。');}
$('tutor-open').addEventListener('click',()=>tutor('依据§5.1–5.6 pp.215–261，梳理球形坍缩、轨道守恒、Jeans方程与无碰撞混合之间的联系，给一道可计算的练习。'));
$('sphere-question').addEventListener('click',()=>{const v=P.spherical(s.theta*PI);tutor(`依据§5.1 pp.215–220与§5.4.4 pp.234–236，EdS无压均匀球，θ/π=${fmt(s.theta)}，r/rta=${fmt(v.radius)}，t/tta=${fmt(v.time)}，ρ/ρbar=${sci(v.densityRatio)}，δ_L=${fmt(v.deltaLinear)}。请区分真实密度反差、线性外推阈值1.686与另加维里假设得到的密度比178。`);});
$('orbit-question').addEventListener('click',()=>tutor(`依据§5.4.5 pp.236–239和§5.4.7 p.243式5.165，固定Plummer势G=M=b=1，r0=2，vr0=0，vt0/vc=${fmt(s.speed,2)}，当前t=${fmt(s.orbitTime,2)}。请解释E、L的守恒，以及为什么一般轨道可能不闭合。数值积分相对能量误差上限${orbitData.maxRelativeEnergyError.toExponential(2)}。`));
$('jeans-question').addEventListener('click',()=>tutor(`依据§5.4.3、§5.4.7 pp.233–234、240–241，稳态球对称尺度自由示踪模型ν∝r^-γ，γ=${fmt(s.gamma,2)}，恒定σr=${s.sigma} km/s，恒定β=${fmt(s.beta,2)}。请推导vc²=(γ−2β)σr²与r=10kpc处的包围质量。σr是三维径向弥散，不是σlos；本例没有验证全局分布函数非负性。`));
$('relax-question').addEventListener('click',()=>tutor(`依据§5.4.1 pp.230–232式5.98，N=${(10**s.logN).toExponential(2)}，tcross=${s.crossing} Myr，trelax≈N/(10lnN)tcross。请核算Gyr结果并解释二体弛豫、直接碰撞与集体无碰撞弛豫的区别。`));
$('mix-question').addEventListener('click',()=>tutor(`依据§5.5.1 pp.249–250，用新增可积教学Hamiltonian H=J−s(J−1)²/2，s=${fmt(s.slope,2)}，J在[.8,1.2]，θ0在[-.18,.18]，t=${fmt(s.mixTime,1)}。Ω=1−s(J−1)，x=√(2J)cosθ,p=−√(2J)sinθ。请解释正则面积.144为何守恒，s=0时何以不剪切，以及这与剧烈弛豫有什么区别。`));
let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>{sphere();orbit();jeans();relaxation();mix();},100);});sphere();orbit();jeans();relaxation();mix();
